// 担当者が通知内の完了リンクを開いたときに実行される。
// クエリ: member, task, token
// token は起票時に発行した使い捨ての値で、URL を知らない第三者が
// 勝手にタスクを閉じられないようにするための最低限の確認。
// 設計: docs/design/04-notification-abstraction.md

const q = $input.first()?.json?.query ?? {};
const memberId = q.member;
const taskId = q.task;
const token = q.token;

if (!memberId || !taskId || !token) {
  throw new Error('task-complete: member / task / token が必要です');
}

return [{ json: { kind: 'members', id: memberId, taskId, token } }];

// タスクを done にし、そのサービスの grant を state に反映する patch を作る。
// grant を書くことでリコンサイラの差分が解消し、以後この操作は再実行されない
// (人手の作業でも、完了すれば宣言的モデルに合流する)。

const ctx = $('リンクを解釈する').first().json;
const rec = $input.first()?.json;

if (!rec || !rec.state) {
  throw new Error(`task-complete: ${ctx.id} の state が見つかりません`);
}

const tasks = Array.isArray(rec.state.tasks) ? rec.state.tasks : [];
const task = tasks.find((t) => t.id === ctx.taskId);

if (!task) throw new Error(`task-complete: タスク ${ctx.taskId} が見つかりません`);

// 完了済みの判定をトークン検証より先に行う。完了時にトークンを消すため、
// リンクを二度開いてもエラーではなく「完了済み」と案内できる(冪等)。
if (task.status === 'done') {
  return [{ json: { __alreadyDone: true, subject: task.subject } }];
}
if (task.token !== ctx.token) throw new Error('task-complete: トークンが一致しません');

const now = new Date().toISOString();
const nextTasks = tasks.map((t) => (t.id === ctx.taskId
  ? { ...t, status: 'done', completed_at: now, token: null, complete_url: null }
  : t));

const grants = {};
if (task.service) {
  // remove 操作の完了なら grant は空になる
  grants[task.service] = task.operation === 'remove' ? [] : (task.grants ?? []);
}

return [{ json: {
  kind: 'members',
  id: ctx.id,
  patch: { tasks: nextTasks, grants, updated_at: now },
  reason: `タスク完了: ${task.id}`,
  __subject: task.subject,
}}];

const subject = $('完了として記録する').first().json.__subject ?? '';
return [{ json: {
  ok: true,
  message: `完了として記録しました: ${subject}`,
}}];

// 二重クリックなど。既に完了しているだけなので成功として返す(冪等)。
const subject = $input.first().json.subject ?? '';
return [{ json: { ok: true, message: `このタスクは既に完了しています: ${subject}` } }];
